package com.zipmediaviewer.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.view.*;import android.widget.*;import android.text.*;import java.io.*;import java.util.*;import java.util.zip.*;
public class MainActivity extends Activity {
 final Handler ui=new Handler(Looper.getMainLooper()); final ArrayList<ZipEntry> items=new ArrayList<>(); ZipFile archive;File cached;LinearLayout list;TextView status;EditText search;int token=0;
 TextView text(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(-1);t.setTextSize(16);t.setPadding(18,18,18,18);return t;}
 public void onCreate(Bundle b){super.onCreate(b);home();}
 void home(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff11151c);setContentView(root);root.addView(text("ZIP Media Viewer"));Button choose=new Button(this);choose.setText("ZIP 파일 열기");choose.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);});root.addView(choose);status=text("압축파일을 선택하세요");root.addView(status);search=new EditText(this);search.setHint("파일 검색");search.setTextColor(-1);root.addView(search);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(Editable e){}});}
 protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==1&&res==RESULT_OK&&data!=null)load(data.getData());}
 boolean video(String s){return s.matches("(?i).*\\.(mp4|mkv|webm|mov|m4v|3gp)$");}
 boolean media(String s){return video(s)||s.matches("(?i).*\\.(jpg|jpeg|png|webp|gif|bmp)$");}
 void load(Uri uri){int id=++token;status.setText("ZIP 불러오는 중...");new Thread(()->{File f=null;ZipFile z=null;try{f=File.createTempFile("archive_",".zip",getCacheDir());try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[131072];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}z=new ZipFile(f);ArrayList<ZipEntry> found=new ArrayList<>();Enumeration<? extends ZipEntry> en=z.entries();while(en.hasMoreElements()){ZipEntry e=en.nextElement();if(!e.isDirectory()&&media(e.getName()))found.add(e);}found.sort((a,b)->a.getName().compareToIgnoreCase(b.getName()));ZipFile ready=z;File tmp=f;ui.post(()->{if(id!=token){try{ready.close();}catch(Exception ignored){}tmp.delete();return;}closeZip();archive=ready;cached=tmp;items.clear();items.addAll(found);status.setText(items.size()+"개 미디어");render();});}catch(Exception ex){if(z!=null)try{z.close();}catch(Exception ignored){}if(f!=null)f.delete();ui.post(()->status.setText("열기 실패: "+ex.getMessage()));}}).start();}
 void render(){if(list==null||search==null)return;list.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);for(int i=0;i<items.size();i++){final int ix=i;ZipEntry e=items.get(i);if(!e.getName().toLowerCase(Locale.ROOT).contains(q))continue;TextView t=text((video(e.getName())?"▶ ":"▣ ")+e.getName());t.setOnClickListener(v->open(ix));list.addView(t);}}
 void open(int i){if(archive==null)return;ZipEntry e=items.get(i);if(video(e.getName()))play(e);else picture(i);}
 void picture(int i){ZipEntry e=items.get(i);ImageView view=new ImageView(this);view.setBackgroundColor(0xff000000);view.setScaleType(ImageView.ScaleType.FIT_CENTER);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(e.getName()).setView(view).setNegativeButton("닫기",null).setNeutralButton("이전",(d,w)->open((i+items.size()-1)%items.size())).setPositiveButton("다음",(d,w)->open((i+1)%items.size())).create();dialog.show();dialog.getWindow().setLayout(-1,(int)(getResources().getDisplayMetrics().heightPixels*.75));ZipFile current=archive;new Thread(()->{try(InputStream in=current.getInputStream(e)){BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeStream(in,null,opt);int sample=1;while(opt.outWidth/sample>2048||opt.outHeight/sample>2048)sample*=2;try(InputStream again=current.getInputStream(e)){BitmapFactory.Options actual=new BitmapFactory.Options();actual.inSampleSize=sample;Bitmap bmp=BitmapFactory.decodeStream(again,null,actual);ui.post(()->{if(dialog.isShowing()&&bmp!=null)view.setImageBitmap(bmp);});}}catch(Exception ex){ui.post(()->status.setText("사진 오류: "+ex.getMessage()));}}).start();}
 void play(ZipEntry e){ZipFile current=archive;status.setText("영상 준비 중...");new Thread(()->{File f=null;try{String name=e.getName();String ext=name.substring(name.lastIndexOf('.'));f=File.createTempFile("video_",ext,getCacheDir());try(InputStream in=current.getInputStream(e);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[131072];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}File ready=f;ui.post(()->{VideoView player=new VideoView(this);player.setVideoPath(ready.getAbsolutePath());player.setMediaController(new MediaController(this));AlertDialog dlg=new AlertDialog.Builder(this).setTitle(e.getName()).setView(player).setPositiveButton("닫기",null).create();dlg.setOnDismissListener(d->{player.stopPlayback();ready.delete();});dlg.show();dlg.getWindow().setLayout(-1,(int)(getResources().getDisplayMetrics().heightPixels*.65));player.setOnPreparedListener(mp->player.start());status.setText("영상 열기 완료");});}catch(Exception ex){if(f!=null)f.delete();ui.post(()->status.setText("영상 오류: "+ex.getMessage()));}}).start();}
 void closeZip(){if(archive!=null)try{archive.close();}catch(Exception ignored){}archive=null;if(cached!=null)cached.delete();cached=null;}
 protected void onDestroy(){token++;closeZip();super.onDestroy();}
}